"""Individually authored follow-up exchanges; measurements come from pinned plans."""
WIDTHS=[1800,1900,2000,1800,1700,2100,1900,2000,1800,2400,1700,1900]
INTRO=[
 [('نجهز شقة في دبي لطفل كثير الحركة.','أي غرفة تريدون أن نبدأ بها، وما الذي يحتاجه الطفل فيها؟'),('الصالة، وأفضّل ترك الوسط للعب.','أضع اللعب ضمن أولوياتكم قبل إضافة قطع جديدة.'),('الكنبة الحالية بلا مقاسات واضحة، فلا نعتمدها.','نبقيها خارج التجربة حتى تُقاس؛ يمكن اختبار مقاس تختارونه لقطعة جديدة.'),('لا أريد تغيير الجدران أو الأبواب.','نحافظ على المخطط، ونراجع الجلسة داخل حدوده.')],
 [('نريد ترتيب فيلا في أبوظبي على مراحل.','هل نبدأ بمساحة العائلة أم استقبال الضيوف؟'),('مساحة العائلة الآن، والمجلس المنخفض لاحقًا.','أبقي طلب المجلس منفصلًا عن تجربة الصالة العائلية.'),('عندنا طابقان، لكن الرسم المقاس لطابق واحد.','لا أستنتج رسم الطابق الغائب أو موضع الدرج من الرسم المتاح.'),('والقرار النهائي نريده بعد مراجعة المصمم.','أعرض اقتراحًا جزئيًا للمراجعة، لا اعتمادًا للفيلا كاملة.')],
 [('شقتنا في الشارقة، ونخشى أن ينكشف الجلوس عند الدخول.','ما الأهم لكم: زيادة المقاعد أم تقليل انكشاف الجلسة؟'),('الخصوصية أولًا، حتى لو قل عدد القطع.','أحفظ هذه الأولوية ولا أفترض أنها تتطلب إغلاق المدخل.'),('نبدأ بكنبة وطاولة من دون وحدة تلفاز.','لن أضيف وحدة تلفاز إلى الاختيار الحالي.'),('هل تحرك الباب لتسهيل الأمر؟','موضع الباب يبقى ثابتًا؛ تغيير الفتحة يحتاج مراجعة أخرى.')],
 [('أريد تجديد فيلا في الرياض، وفيها طابقان.','ما القياسات المتاحة الآن، وما الذي لا يزال ناقصًا؟'),('مستوى واحد فقط؛ لا يوجد قياس للدرج.','نؤجل الدرج والطابق الآخر بدل نسخ مستوى فوق مستوى.'),('المجلس غير صالة العائلة؛ لا تخلطهما.','أتعامل معهما كمساحتين مختلفتين في الطلب.'),('لن نعتمد شيئًا قبل المصمم.','تبقى التجربة اقتراحًا، ويُذكر ما لم يُقَس في الملاحظات.')],
 [('صالتنا في جدة تحتاج قطعًا أقل.','هل تريدون زيادة الجلوس أم تقليل ازدحام الغرفة؟'),('تقليل الازدحام، ولا نريد خزانة جديدة.','أستبعد الخزانة من قائمة ما سنجربه الآن.'),('لا تستنتج حجم الأثاث من الصور.','أعتمد أبعادًا تذكرونها صراحة لكل قطعة نجربها.'),('ونؤجل الإكسسوارات حتى نرى الفراغ.','تبقى الإكسسوارات خطوة لاحقة بعد مراجعة الجلسة.')],
 [('نرتب شقة في الدمام ونحب هدوء الألوان.','هل المطلوب تغيير الأثاث كله أم تجربة جلسة أولية؟'),('تجربة جلسة، ولا نختار القماش اليوم.','نفصل مكان القطع عن قرار عينة القماش.'),('ولا نحدد موضع الإضاءة من صورة السقف.','تحتاج نقاط الإضاءة إلى قياس ومراجعة التوصيلات.'),('سأرسل الرسم المقاس للصالة.','سأحافظ على الفتحات الظاهرة فيه أثناء تجربة الأثاث.')],
 [('بيتنا في الدوحة ونريد مجلسًا وصالة للعائلة.','هل ترغبون في البدء بإحدى المساحتين فقط؟'),('بالعائلة؛ وحدات المجلس لم نختر مقاسها.','أبقي المجلس معلقًا حتى تتحدد وحداته بدل ملئه بقطع مختلفة.'),('قد نراجع فصل المداخل لاحقًا.','لا أعدّل المداخل في التجربة الحالية.'),('جربوا كنبة عادية للصالة فقط.','اختيارها للصالة لا يغير طلب الجلسة الخاصة بالمجلس.')],
 [('عندنا شقة في لوسيل، واستقبال الضيوف مهم.','هل المساحة التي سنرتبها الآن للاستقبال أم للعائلة؟'),('للعائلة، والمجلس له طلب مستقل.','لن أدمج الوظيفتين من دون موافقتكم.'),('أبغى أشوف مقاسات فعلية لا شكلًا تقريبيًا.','كل قطعة في التجربة لها عرض وعمق محددان.'),('ولا تعدني بأن الأبواب تفتح براحة قبل القياس.','اتجاه الفتح الفعلي نقطة يجب التأكد منها في المكان.')],
 [('نجهز شقة في مدينة الكويت ونريد ضبط المصاريف.','ما القطع التي تريدون اختبارها قبل التفكير في شراء غيرها؟'),('كنبة وطاولة؛ الأثاث القديم لا نعرف عمقه.','لا أدخله كقطعة مقاسة قبل تحديد أبعاده.'),('المصعد ضيق وقد يؤثر على النقل.','فحص مسار النقل منفصل عن مناسبة القطعة داخل الصالة.'),('نبدأ بالرسم ثم نراجع النقل.','أحتفظ بمسألة المصعد في قائمة التحقق قبل التصنيع.')],
 [('شقتنا في السالمية والكنبة التي نريدها طولها ٢٤٠ سم.','هل هذا طول مطلوب لقطعة جديدة أم قياس قطعة موجودة؟'),('مطلوب لقطعة جديدة، لا تغيّره من نفسك.','أبقي الطول ثابتًا، وإن ظهرت مشكلة أشرحها بدل تصغيره.'),('ميزانيتنا محدودة ولا نريد مقاعد إضافية.','تظل التجربة بكنبة وطاولة فقط إلى أن تراجعوا النتيجة.'),('نرسل المقاسات للمصمم قبل طلب السعر.','يحتاج السعر إلى الخامة والتشطيب ومراجعة التنفيذ أيضًا.')],
 [('بنجهز شقة في القاهرة ونحب نبدأ بالصالة.','هل نختبر قطعًا جديدة أم قطعًا تملكون مقاساتها؟'),('جديدة؛ الصور اللي عندنا للألوان بس.','لا أستخدم الصور دليلًا على القياس أو خامة مضمونة.'),('عايزين حل بسيط، مش أوضة مليانة.','أقتصر على الجلسة الأساسية التي ستحددونها.'),('والحائط زي ما هو.','أحافظ على هندسة الغرفة من دون تعديل الجدران.')],
 [('عندنا شقة في الدار البيضاء ونريد جلسة للعائلة.','هل نبدأ بالأثاث أم باختيار السجاد والستائر؟'),('بالأثاث أولًا، ثم نجرب بقية العناصر.','أبقي مساحة السجادة وفتحة الستارة للمراجعة بعد الجلسة.'),('بغينا اقتراحًا نناقشه، ماشي قرار نهائي.','التوزيع الأول قابل للتعديل معكم ومع المصمم.'),('وما تبدل حتى قياس بلا ما تقول لنا.','أذكر أي تعارض يظهر قبل أن أقترح تغيير مقاس قطعة.')]
]
PAIRS=[
 [('أرسلت الآن المخطط المقاس؛ مساحة الصالة فيه {area} متر مربع. نبدأ بها قبل بقية الشقة.','نرتب الجلسة العائلية أولًا، مع إبقاء الأبواب كما تظهر في المخطط. ما زال اتجاه فتح الأبواب يحتاج تأكيدًا في المكان.'),('أختار كنبة بعرض {width} وعمق 820 مم وطاولة 900 في 550 مم.','أستخدم أبعاد القطعتين كاملة في التجربة، من دون تصغيرهما كي تبدوا مناسبتين.'),('هل بقي مكان للعب ابني بين الأثاث؟','{outcome} مكان اللعب احتياج مهم، لكن مساحته المريحة تحتاج مراجعة معكم؛ نجاح وضع القطع وحده لا يضمنها.'),('اعرض هذا الاقتراح على المصمم قبل الشراء.','أرفق المقاسات والتوزيع الأول مع رغبتكم في مساحة اللعب، ويقرر المصمم معكم ما يلزم تعديله قبل اعتماد القطع.')],
 [('وصل مخطط طابق واحد؛ الصالة العائلية فيه {area} متر مربع. لن نلمس المجلس الآن.','أفصل العمل على صالة العائلة عن المجلس المنخفض. مخطط الطابق الآخر والدرج ما زالا مطلوبين، ولا أنسخ هذا الطابق مكانهما.'),('لهذه الصالة فقط كنبة عادية بعرض {width} وعمق 820 مم، وطاولة 900 في 550 مم.','أجرب هاتين القطعتين في صالة العائلة؛ اختيار الكنبة هنا لا يبدل طلبكم لجلسة المجلس.'),('أريد رؤية ما أمكن وضعه فعلًا.','{outcome} لا تعني هذه الخطوة أن المجلسين أو الفيلا كاملة قد حُسما.'),('ضع الطابق العلوي والمجلس في قائمة المؤجل للمصمم.','يصل الاقتراح بوصفه عملًا جزئيًا لصالة واحدة، مع تنبيه واضح إلى أبعاد وحدات المجلس ومخطط الأعلى والدرج الناقصة.')],
 [('هذا مخطط الصالة بمساحة {area} متر مربع؛ لا تغيروا جدار المدخل.','نحافظ على حدود الغرفة والمدخل، ونجرب الأثاث داخلها قبل مناقشة أي تعديل في الجدران.'),('ابدأ بكنبة {width} في 820 مم وطاولة 900 في 550 مم، من غير كرسي إضافي.','أحصر الاختيار في الكنبة والطاولة كي لا أملأ الصالة بقطعة لم تطلبوها.'),('ولو أعجبني المنظر، هل أقدر أعتمده مباشرة؟','{outcome} يبقى هذا اقتراحًا للمراجعة؛ نعتمد المقاسات والخامة مع المصمم بعد التحقق من الأبواب في الموقع.'),('اكتب له أن الخصوصية عند الدخول أهم من إضافة مقعد.','أضيف أولوية الخصوصية إلى الملاحظات مع القطعتين المختارتين، ليوازن المصمم بين خط النظر والحركة معكم.')],
 [('عندي الآن مخطط مستوى واحد؛ الصالة فيه {area} متر مربع، وباقي الفيلا لم نقسه.','نكمل ما تسمح به قياسات هذا المستوى فقط. لا أستنتج مقاس الدرج أو توزيع المستوى الآخر من هذا الرسم.'),('نشتغل على صالة العائلة بكنبة {width} وعمق 820 مم وطاولة 900 في 550 مم. المجلس مستقل.','أبقي المجلس مستقلًا ومعلقًا، وأختبر الكنبة والطاولة لصالة الاستخدام اليومي وحدها.'),('هل جاءت القطعتان داخل الصالة من غير تعديل المقاس؟','{outcome} أبعاد المجلس المنخفض ومداخله لم تدخل في هذه التجربة.'),('خل المصمم يراجع الطابقين قبل ما يعطي رأيه النهائي.','أضع الرسم الجزئي وما لم يُقَس بعد في ملف المراجعة، ولا أقدمه كتوزيع نهائي لبيت من طابقين.')],
 [('المخطط المقاس وصل، والصالة {area} متر مربع. أريد حلًا صغيرًا بدل الأثاث الكبير.','نبدأ بقطعتين معتدلتين ونترك بقية الفراغ للمراجعة؛ لا أضيف خزائن قبل تحديد ما تريدون الاحتفاظ به.'),('خذ كنبة بعرض {width} وعمق 820 مم وطاولة 900 في 550 مم.','أثبت هذه الأبعاد، وأقارنها بحدود الغرفة ومواضع الفتحات الموجودة في الرسم.'),('ما نتيجة المحاولة الأولى؟','{outcome} إذا احتجتم مقعدًا آخر فسنختبره كطلب جديد بدل افتراض وجود مساحة كافية.'),('جهز المقاسات، ولا تعدني بسعر نهائي.','أجمع المقاسات والاختيار المقترح للمصمم؛ التكلفة تحتاج اختيار القماش والتشطيب ومراجعة التنفيذ، ولا أضع رقمًا مؤكدًا الآن.')],
 [('هذه الصالة في المخطط؛ مساحتها {area} متر مربع، وأريد أن تبقى هادئة.','سأبدأ بتوزيع واضح وقليل القطع، ثم نناقش اللون والإنارة من دون تحويل الإحساس المطلوب إلى وعد بقياسات غير معروفة.'),('كنبة {width} في 820 مم وطاولة 900 في 550 مم تكفينا كبداية.','أجرب المقاسين كما طلبتم؛ لون القماش لا يغير المساحة التي تشغلها الكنبة في الرسم.'),('وريني النتيجة قبل ما نختار الستارة.','{outcome} نختار الستارة بعد قياس فتحتها وموضع السكة، فلا نخلط عرض الغرفة بعرض الشباك.'),('اترك اختيار الإنارة للمراجعة مع المصمم.','يحتوي الملخص على الجلسة المقترحة، بينما تظل نقاط الكهرباء ونوع وحدات الإنارة مسائل يراجعها المصمم معكم.')],
 [('وصل مخطط بمساحة صالة {area} متر مربع. أوافق على تجربة صالة العائلة، لا المجلس.','نحافظ على هذا الفصل بوضوح. المجلس الذي طلبتموه لا يتحول إلى كنبة عادية بسبب تجربة غرفة أخرى.'),('للصالة كنبة {width} بعمق 820 مم وطاولة 900 في 550 مم.','أضع هاتين القطعتين في طلب صالة العائلة فقط، وأبقي أبعاد المجلس وممراته خارج ما يمكن اعتماده اليوم.'),('هل نجحت تجربة الصالة؟','{outcome} ليست هذه نتيجة لاختبار وحدات المجلس، فهي لم تُحدد بعد.'),('أرسل المسألتين منفصلتين للمصمم.','يفصل ملخصه بين اقتراح صالة العائلة وطلب المجلس المعلق؛ ويظل القرار في ربط الغرف وتنفيذ الجلسات للمصمم معكم.')],
 [('المخطط يوضح صالة مساحتها {area} متر مربع. أريد البدء بالعائلة بعيدًا عن استقبال الضيوف.','يمكن ترتيب هذه الصالة دون حسم مساحة استقبال الضيوف. نراجع المداخل معكم بدل افتراض أن الفصل يناسب كل البيت.'),('ضع كنبة {width} في 820 مم وطاولة 900 في 550 مم في صالة العائلة.','أتعامل معهما كاختيار لهذه الغرفة وحدها؛ لا أستخدمهما بديلًا عن المجلس الذي بقيت تفاصيله ناقصة.'),('أبغى النتيجة كما هي، حتى لو تحتاج تعديل.','{outcome} أعرض المحاولة بما فيها، ولا أغير مقاس قطعة في الخفاء لتحسين شكلها.'),('خلي المصمم يقرر بعد ما يشوف توزيع الضيوف أيضًا.','أضم اقتراح الصالة وقائمة ما يلزم للمجلس إلى المراجعة، مع توضيح أن استقبال الضيوف لم يكتمل تصميمه.')],
 [('أضفت مخطط الشقة؛ مساحة الصالة {area} متر مربع. نريد تقليل المشتريات.','نختبر ترتيبًا محدودًا أولًا، وتبقى قطعكم الحالية في قائمة القياس بدل تقدير أحجامها من الصور.'),('هذه التجربة بكنبة {width} وعمق 820 مم وطاولة 900 في 550 مم فقط.','أختبر القطعتين المحددتين، ولا أعتبر قطعة قديمة مقاسة ما دام طولها وعمقها غير مسجلين.'),('هل ظهرت مشكلة في إدخالهما إلى الغرفة؟','{outcome} هذا فحص للمكان داخل الصالة، وليس ضمانًا لمرور القطع في المصعد أو السلم؛ ذلك يحتاج قياس مسار النقل.'),('نراجع طريق النقل قبل أي طلب تصنيع.','أسجل طريق النقل نقطة مستقلة للمصمم، مع المقاسات والتوزيع الداخلي قبل أن يوصي بالتصنيع.')],
 [('الحين عندي مخطط مقاس؛ مساحة الصالة {area} متر مربع. خلنا نحافظ على طول الكنبة ٢٤٠ سم.','أحافظ على ٢٤٠ سم كما كتبتموها، أي ٢٤٠٠ مم، ولا أحولها إلى طول أصغر حتى تبدو مناسبة.'),('نعم، العمق ٨٢٠ مم والطاولة ٩٠٠ في ٥٥٠ مم، ولا تضيف قطعة ثانية.','أستخدم الكنبة بطول ٢٤٠٠ مم والطاولة بالمقاسين المحددين، ولا أضيف مقعدًا أو خزانة.'),('وش طلعت النتيجة بهالمقاس؟','{outcome} يبقى العرض المطلوب ثابتًا؛ لا أعدكم بفراغ حركة مريح قبل مراجعة الأبواب في المكان.'),('اعرضها على المصمم ومعها سقف الميزانية اللي اتفقنا عليه.','أرفق أبعاد القطعتين والميزانية المطلوبة للمراجعة؛ اقتراح الشكل وحده لا يحدد سعر التنفيذ أو يعني موافقة المصمم.')],
 [('بعتّ مخطط الصالة المقاس، ومساحتها {area} متر مربع. نبدأ باللي نقدر عليه.','نبدأ باختيار واضح ومحدود، ونترك أي قطعة غير مقاسة للمراجعة بدل الاعتماد على الصورة وحدها.'),('خلّي الكنبة {width} وعمقها 820 مم والطاولة 900 في 550 مم.','أثبت المقاسات في التجربة، وأحافظ على حدود الغرفة والفتحات بدل تحريك الحائط لتسهيل وضع القطع.'),('ينفع أشوف المحاولة قبل ما أقرر القماش؟','{outcome} بعدها يمكن مقارنة عينات القماش؛ الرسم لا يثبت ملمس الخامة أو مقاومتها للاستعمال.'),('تمام، المصمم يراجع الاختيار معانا قبل التنفيذ.','أجهز ملاحظات الصالة والمقاسات المعروفة والأسئلة المتبقية، ويعتمد المصمم معكم التوزيع والخامات بعد المراجعة.')],
 [('أرسلت المخطط بالمقاسات؛ الصالة {area} متر مربع. بغينا نجرب جلسة بسيطة للعائلة.','نركز على هذه الصالة أولًا، ونترك الاختيارات الزخرفية إلى أن تتضح المساحة التي تشغلها القطع.'),('نختار كنبة {width} في 820 مم وطاولة 900 في 550 مم.','أجرب كنبة واحدة وطاولة بهذه الأبعاد، ولا أملأ باقي المساحة بعناصر لم تختاروها.'),('شنو بان فالتوزيع الأول؟','{outcome} تبقى تجربة قابلة للتعديل، ولا تعني أن تفاصيل الصنع أو الخامة قد اعتمدت.'),('خلي المصمم يناقش معنا السجاد والستائر بعد هاد الخطوة.','أوصل رغبتكم في مناقشة السجاد والستائر مع اقتراح الجلسة؛ المقاسات النهائية والعينات والتفاصيل يراجعها المصمم معكم.')]
]
